package org.eclipse.kura.rest.configuration.provider.test;

import static org.junit.Assert.assertTrue;

import org.eclipse.kura.core.testutil.requesthandler.AbstractRequestHandlerTest;
import org.eclipse.kura.core.testutil.requesthandler.MqttTransport;
import org.eclipse.kura.core.testutil.requesthandler.Transport.MethodSpec;
import org.junit.Test;

/**
 * Feature: requests received through the cloud request handler (MQTT) are trusted and keep full access to the
 * UserAdmin store configuration.
 */
public class UserStoreAccessMqttTest extends AbstractRequestHandlerTest {

    private static final String USER_STORE_PID = "org.eclipse.kura.internal.useradmin.store.RoleRepositoryStoreImpl";
    // SHA-256 of "admin", without the trailing base64 padding that Gson escapes as a unicode sequence
    private static final String ADMIN_PASSWORD_HASH = "jGl25bVBBBW96Qi9Te4V37Fnqchz/Eu4qB9vKrRIqRg";

    private static final MqttTransport MQTT_TRANSPORT = new MqttTransport("CONF-V2");

    public UserStoreAccessMqttTest() {
        super(MQTT_TRANSPORT);
    }

    /*
     * Scenarios
     */

    @Test
    public void cloudRequestListsUserStoreConfiguration() {
        whenRequestIsPerformed(new MethodSpec("GET"), "/configurableComponents/configurations");

        thenRequestSucceeds();
        thenResponseContainsUserStoreWithAdminPasswordHash();
    }

    @Test
    public void cloudRequestReadsUserStoreConfigurationByPid() {
        whenRequestIsPerformed(new MethodSpec("POST"), "/configurableComponents/configurations/byPid",
                "{\"pids\":[\"" + USER_STORE_PID + "\"]}");

        thenRequestSucceeds();
        thenResponseContainsUserStoreWithAdminPasswordHash();
    }

    /*
     * Steps
     */

    /*
     * Then
     */

    private void thenResponseContainsUserStoreWithAdminPasswordHash() {
        final String body = expectResponse().body.orElseThrow(() -> new IllegalStateException("expected body"));
        assertTrue("expected user store in response", body.contains("\"pid\":\"" + USER_STORE_PID + "\""));
        assertTrue("expected admin credentials in response", body.contains(ADMIN_PASSWORD_HASH));
    }
}
